def main():
    rows = []
    for i, (tag, pos, neg, reason, incidental) in enumerate(CONCEPTS, 1):
        rows.append(dict(id=f"D{i:02}P", split="development", source_type="synthetic",
                         text=pos, suitable_concepts=[tag], forbidden_concepts=[],
                         acceptable_no_match=False, semantic_basis=reason))
        rows.append(dict(id=f"D{i:02}N", split="development", source_type="synthetic",
                         text=neg, suitable_concepts=incidental, forbidden_concepts=[tag],
                         acceptable_no_match=True, semantic_basis=reason))
    for i, (text, yes, no, skip, why) in enumerate(ACCEPTANCE, 1):
        rows.append(dict(id=f"A{i:02}", split="acceptance", source_type="synthetic",
                         text=text, suitable_concepts=yes, forbidden_concepts=no,
                         acceptable_no_match=skip, semantic_basis=why))
    path = ROOT / "evaluation.jsonl"
    if path.exists():
        raise SystemExit("Evaluation is frozen: refusing overwrite")
    path.write_text("".join(json.dumps(r, ensure_ascii=False)+"\n" for r in rows), encoding="utf-8")
    (ROOT / "evaluation_lock.json").write_text(json.dumps({
        "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
        "order": "evaluation frozen before candidates; acceptance is reporting-only",
        "sample_count": len(rows), "acceptance_count": len(ACCEPTANCE),
        "source": "all synthetic; one semantic judgement incorporates user clarification about aftersex",
    }, ensure_ascii=False, indent=2)+"\n", encoding="utf-8")
    print(f"Frozen {len(rows)} samples, {len(ACCEPTANCE)} acceptance")


if __name__ == "__main__":
    main()
